package dev.abros.anthub.core;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import java.nio.file.*;import java.util.jar.*;import static org.junit.jupiter.api.Assertions.*;
class ModDuplicatesTest {@TempDir Path directory;void jar(String file,String id)throws Exception{try(var out=new JarOutputStream(Files.newOutputStream(directory.resolve(file)))){out.putNextEntry(new JarEntry("META-INF/neoforge.mods.toml"));out.write(("[[mods]]\nmodId = \""+id+"\"\nversion = \"1\"\n").getBytes(java.nio.charset.StandardCharsets.UTF_8));out.closeEntry();}}@Test void detectsIdentityRegardlessOfFilenameAndDoesNotExecuteJar()throws Exception{jar("a.jar","sample");jar("renamed.jar","sample");jar("different.jar","different");Files.writeString(directory.resolve("unreadable.jar"),"bad");var result=ModDuplicates.scan(directory);assertEquals(1,result.size());assertTrue(result.getFirst().contains("a.jar"));assertTrue(result.getFirst().contains("renamed.jar"));assertFalse(result.getFirst().contains("different.jar"));}}
